import { describe, expect, it } from "vitest";
import { createApp } from "../src/app.ts";
import { openDatabase } from "../src/db.ts";
import { creatorSales, registerCreator } from "../src/store.ts";
import { order } from "./helpers.ts";

const HUGE = "999999999999.99"; // o maior valor que o contrato aceita por pedido: 99.999.999.999.999 centavos

function harness() {
  const db = openDatabase(":memory:");
  const app = createApp(db);
  registerCreator(db, { id: "crt_ana", couponCode: "ANA10", utmHandle: "ana" });
  const post = (path: string, body: unknown) => app.request(path, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
  const sales = async () => ({ ...(await (await app.request("/creators/crt_ana/sales")).json() as any) });
  return { db, app, post, sales };
}

describe("agregados exatos além do inteiro seguro do JavaScript", () => {
  it("91 pedidos válidos de 999.999.999.999,99 somam além de 2^53 e a consulta responde com o valor exato, não 500", async () => {
    const { post, app } = harness();
    for (let i = 1; i <= 91; i += 1) expect((await post("/webhooks/orders", order({ id: i, total_price: HUGE, discount_codes: [{ code: "ana10" }] }))).status).toBe(201);
    const res = await app.request("/creators/crt_ana/sales");
    expect(res.status).toBe(200);
    expect(await res.json()).toEqual({
      creator_id: "crt_ana",
      orders: 91,
      gross_cents: null, // não cabe num número JSON sem perder centavos: o valor está em exact
      refunded_cents: 0,
      net_cents: null,
      exact: { gross_cents: "9099999999999909", refunded_cents: "0", net_cents: "9099999999999909" },
    });
  });

  it("bruto enorme com líquido pequeno: o bruto só sai exato, os outros dois cabem num número", async () => {
    const { post, sales } = harness();
    for (let i = 1; i <= 91; i += 1) {
      await post("/webhooks/orders", order({ id: i, total_price: HUGE, discount_codes: [{ code: "ana10" }] }));
      if (i !== 91) await post("/webhooks/refunds", { id: `r${i}`, order_id: String(i), amount: HUGE });
    }
    const result = await sales();
    expect(result).toMatchObject({ gross_cents: null, refunded_cents: 8_999_999_999_999_910, net_cents: 99_999_999_999_999 });
    expect(result.exact).toEqual({ gross_cents: "9099999999999909", refunded_cents: "8999999999999910", net_cents: "99999999999999" });
  });

  it("valores pequenos continuam saindo como número, e o exato acompanha", async () => {
    const { post, sales } = harness();
    await post("/webhooks/orders", order({ id: 1, total_price: "100.00", discount_codes: [{ code: "ANA10" }] }));
    await post("/webhooks/refunds", { id: "r1", order_id: "1", amount: "30.00" });
    expect(await sales()).toEqual({
      creator_id: "crt_ana",
      orders: 1,
      gross_cents: 10000,
      refunded_cents: 3000,
      net_cents: 7000,
      exact: { gross_cents: "10000", refunded_cents: "3000", net_cents: "7000" },
    });
  });

  it("o inteiro seguro exato ainda sai como número; um centavo acima só como texto", () => {
    const db = openDatabase(":memory:");
    registerCreator(db, { id: "crt_ana", couponCode: "ANA10", utmHandle: "ana" });
    const insert = db.prepare("INSERT INTO orders (id, total_cents, currency, financial_status, counted, creator_id, attribution_json, received_at) VALUES (?, ?, 'BRL', 'paid', 1, 'crt_ana', '{}', 'x')");
    insert.run("a", 9_007_199_254_740_000);
    insert.run("b", 991);
    expect(creatorSales(db, "crt_ana")).toMatchObject({ gross_cents: Number.MAX_SAFE_INTEGER, exact: { gross_cents: "9007199254740991" } });
    insert.run("c", 1);
    expect(creatorSales(db, "crt_ana")).toMatchObject({ gross_cents: null, net_cents: null, exact: { gross_cents: "9007199254740992", net_cents: "9007199254740992" } });
  });

  it("quando a soma passa de 64 bits no próprio SQLite, o resultado continua exato", () => {
    const db = openDatabase(":memory:");
    registerCreator(db, { id: "crt_ana", couponCode: "ANA10", utmHandle: "ana" });
    db.exec(`WITH RECURSIVE n(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM n WHERE i < 100000)
             INSERT INTO orders (id, total_cents, currency, financial_status, counted, creator_id, attribution_json, received_at)
             SELECT 'o' || i, 99999999999999, 'BRL', 'paid', 1, 'crt_ana', '{}', 'x' FROM n`);
    const refund = db.prepare("INSERT INTO refunds (id, order_id, requested_cents, applied_cents, status, received_at) VALUES (?, ?, ?, ?, 'applied', 'x')");
    refund.run("r1", "o1", 5_000, 5_000);
    refund.run("r2", "o2", 700, 700);
    const result = creatorSales(db, "crt_ana");
    expect(result.orders).toBe(100_000);
    expect(result.gross_cents).toBeNull();
    expect(result.refunded_cents).toBe(5_700);
    expect(result.exact).toEqual({ gross_cents: "9999999999999900000", refunded_cents: "5700", net_cents: "9999999999999894300" });
  });

  it("criador sem vendas: zeros em número e em texto", async () => {
    const { sales } = harness();
    expect(await sales()).toEqual({ creator_id: "crt_ana", orders: 0, gross_cents: 0, refunded_cents: 0, net_cents: 0, exact: { gross_cents: "0", refunded_cents: "0", net_cents: "0" } });
  });
});

test/properties.test.ts.source:
import fc from "fast-check";
import { describe, expect, it } from "vitest";
import { openDatabase } from "../src/db.ts";
import { allocateRefund } from "../src/refunds.ts";
import { getOrder, ingestOrder, ingestRefund } from "../src/store.ts";
import { toCents } from "../src/money.ts";

const now = () => "2026-06-01T00:00:00.000Z";
const signals = { couponCodes: [], utmHandle: null };

describe("invariantes de estorno", () => {
  it("para qualquer ordem de chegada (inclusive estorno antes do pedido), o estornado é min(total, soma pedida) e nunca passa do total", () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 0, max: 100_000 }),
        fc.array(fc.integer({ min: 1, max: 60_000 }), { minLength: 1, maxLength: 8 }),
        fc.nat(),
        (total, amounts, orderPosition) => {
          const db = openDatabase(":memory:");
          const events: Array<() => void> = amounts.map((amount, i) => () =>
            void ingestRefund(db, { id: `r${i}`, orderId: "1", amountCents: amount }, now),
          );
          events.splice(
            orderPosition % (events.length + 1),
            0,
            () => void ingestOrder(db, { id: "1", totalCents: total, currency: "BRL", financialStatus: "paid", createdAt: null, signals }, now),
          );
          events.forEach((run) => run());

          const result = getOrder(db, "1")!;
          const requested = amounts.reduce((a, b) => a + b, 0);
          expect(result.refunded_cents).toBe(Math.min(total, requested));
          expect(result.refunded_cents).toBeLessThanOrEqual(total);
          expect(result.net_cents).toBeGreaterThanOrEqual(0);
          expect(result.refunds).toHaveLength(amounts.length);
          expect(result.refunds.every((r) => r.status !== "pending")).toBe(true);
          // o histórico guarda o que foi pedido, mesmo quando foi cortado
          expect(result.refunds.reduce((s, r) => s + r.requested_cents, 0)).toBe(requested);
        },
      ),
      { numRuns: 200 },
    );
  });

  it("reenviar qualquer evento já recebido não muda o resultado", () => {
    fc.assert(
      fc.property(fc.array(fc.integer({ min: 1, max: 5000 }), { minLength: 1, maxLength: 6 }), (amounts) => {
        const once = openDatabase(":memory:");
        const twice = openDatabase(":memory:");
        for (const db of [once, twice]) {
          ingestOrder(db, { id: "1", totalCents: 8000, currency: "BRL", financialStatus: "paid", createdAt: null, signals }, now);
        }
        amounts.forEach((a, i) => {
          ingestRefund(once, { id: `r${i}`, orderId: "1", amountCents: a }, now);
          ingestRefund(twice, { id: `r${i}`, orderId: "1", amountCents: a }, now);
          ingestRefund(twice, { id: `r${i}`, orderId: "1", amountCents: a }, now);
        });
        expect(getOrder(twice, "1")).toEqual(getOrder(once, "1"));
      }),
    );
  });
});

describe("allocateRefund", () => {
  it("aplica tudo quando cabe", () => {
    expect(allocateRefund(10000, 2000, 3000)).toEqual({ applied: 3000, status: "applied" });
  });
  it("aplica exatamente o que sobra quando bate no teto, sem marcar corte", () => {
    expect(allocateRefund(10000, 7000, 3000)).toEqual({ applied: 3000, status: "applied" });
  });
  it("corta o excedente", () => {
    expect(allocateRefund(10000, 7000, 3001)).toEqual({ applied: 3000, status: "clamped" });
  });
  it("não aplica nada quando já está tudo estornado", () => {
    expect(allocateRefund(10000, 10000, 1)).toEqual({ applied: 0, status: "clamped" });
  });
});

describe("toCents", () => {
  it.each([
    ["100.00", 10000],
    ["0.5", 50],
    ["1", 100],
    ["19.99", 1999],
    [12.3, 1230],
  ])("%s -> %s", (input, cents) => expect(toCents(input)).toBe(cents));
  it.each(["", "abc", "-1", "1.234", "1,50", null, undefined, NaN, {}])("recusa %s", (input) =>
    expect(toCents(input)).toBeNull(),
  );
});

test/refunds.test.ts.source:
import { describe, expect, it } from "vitest";
import { setup } from "./helpers.ts";

async function withOrder() {
  const t = setup();
  await t.creator("crt_ana", "ANA10", "ana");
  await t.order({ id: 1, total_price: "100.00", discount_codes: [{ code: "ANA10" }] });
  return t;
}

describe("estornos", () => {
  it("estorno parcial reduz o líquido, mantém a atribuição e o histórico", async () => {
    const t = await withOrder();
    const res = await t.refund({ id: "r1", order_id: 1, amount: "30.00" });
    expect(res.body).toMatchObject({ result: "applied", applied_cents: 3000 });

    const order = (await t.get("/orders/1")).body;
    expect(order.attribution.creator_id).toBe("crt_ana");
    expect(order.refunded_cents).toBe(3000);
    expect(order.net_cents).toBe(7000);
    expect(order.refunds).toHaveLength(1);

    expect((await t.get("/creators/crt_ana/sales")).body).toMatchObject({
      orders: 1,
      gross_cents: 10000,
      refunded_cents: 3000,
      net_cents: 7000,
    });
  });

  it("estorno repetido (mesmo id) não é somado de novo", async () => {
    const t = await withOrder();
    await t.refund({ id: "r1", order_id: 1, amount: "30.00" });
    const again = await t.refund({ id: "r1", order_id: 1, amount: "30.00" });

    expect(again.status).toBe(200);
    expect(again.body.result).toBe("duplicate");
    const order = (await t.get("/orders/1")).body;
    expect(order.refunded_cents).toBe(3000);
    expect(order.refunds).toHaveLength(1);
  });

  it("estornos distintos que passariam do total são cortados no teto e o corte fica rastreável", async () => {
    const t = await withOrder();
    await t.refund({ id: "r1", order_id: 1, amount: "80.00" });
    const second = await t.refund({ id: "r2", order_id: 1, amount: "50.00" });
    const third = await t.refund({ id: "r3", order_id: 1, amount: "10.00" });

    expect(second.body).toMatchObject({ result: "clamped", requested_cents: 5000, applied_cents: 2000 });
    expect(third.body).toMatchObject({ result: "clamped", requested_cents: 1000, applied_cents: 0 });

    const order = (await t.get("/orders/1")).body;
    expect(order.refunded_cents).toBe(10000);
    expect(order.net_cents).toBe(0);
    expect(order.refunds.map((r: any) => [r.id, r.requested_cents, r.applied_cents, r.status])).toEqual([
      ["r1", 8000, 8000, "applied"],
      ["r2", 5000, 2000, "clamped"],
      ["r3", 1000, 0, "clamped"],
    ]);
  });

  it("estorno total zera o líquido sem apagar a venda nem o histórico", async () => {
    const t = await withOrder();
    await t.refund({ id: "r1", order_id: 1, amount: "100.00" });
    const sales = (await t.get("/creators/crt_ana/sales")).body;
    expect(sales).toMatchObject({ orders: 1, gross_cents: 10000, refunded_cents: 10000, net_cents: 0 });
  });

  it("estorno que chega antes do pedido fica pendente e é aplicado quando o pedido chega", async () => {
    const t = setup();
    await t.creator("crt_ana", "ANA10", "ana");
    const early = await t.refund({ id: "r1", order_id: 1, amount: "30.00" });
    expect(early.status).toBe(202);
    expect(early.body.result).toBe("pending");

    await t.order({ id: 1, total_price: "100.00", discount_codes: [{ code: "ANA10" }] });

    const order = (await t.get("/orders/1")).body;
    expect(order.refunded_cents).toBe(3000);
    expect(order.refunds).toMatchObject([{ id: "r1", status: "applied", applied_cents: 3000 }]);
    expect((await t.get("/creators/crt_ana/sales")).body.net_cents).toBe(7000);
  });

  it("estornos pendentes respeitam o teto quando o pedido chega", async () => {
    const t = setup();
    await t.refund({ id: "r1", order_id: 1, amount: "70.00" });
    await t.refund({ id: "r2", order_id: 1, amount: "70.00" });
    await t.order({ id: 1, total_price: "100.00" });

    const order = (await t.get("/orders/1")).body;
    expect(order.refunded_cents).toBe(10000);
    expect(order.refunds.map((r: any) => [r.id, r.applied_cents, r.status])).toEqual([
      ["r1", 7000, "applied"],
      ["r2", 3000, "clamped"],
    ]);
  });

  it("estorno pendente repetido continua sendo um só", async () => {
    const t = setup();
    await t.refund({ id: "r1", order_id: 1, amount: "30.00" });
    const again = await t.refund({ id: "r1", order_id: 1, amount: "30.00" });
    expect(again.body.result).toBe("duplicate");
    await t.order({ id: 1, total_price: "100.00" });
    expect((await t.get("/orders/1")).body.refunded_cents).toBe(3000);
  });

  it("rejeita estorno com valor inválido", async () => {
    const t = await withOrder();
    expect((await t.refund({ id: "r1", order_id: 1, amount: "0" })).status).toBe(400);
    expect((await t.refund({ id: "r2", order_id: 1, amount: "-1.00" })).status).toBe(400);
    expect((await t.refund({ id: "r3", order_id: 1, amount: "x" })).status).toBe(400);
  });
});

